css:
body {
    margin: 0;
    padding: 0;
    background: #fff;
    font-family: monospace;
}
* {
    font-family: Courier, monospace !important;
}


table, tr, td {
    margin: 0px !important;
    padding: 0;
    border-spacing: 0;
    border-collapse: collapse;
}

.main-table {
    width: 98%;
    margin: 18px auto;
    border-collapse: separate;
    border-spacing: 8px;
    background: #fff;
    table-layout: fixed;
}

.main-table td, .main-table th {
    padding: 0;
}

.header-logo {
    padding: 10px 10px 0 10px;
    vertical-align: top;
    border-left: none !important;
    border-bottom: none !important;
    width: 40%;
}

.logo-container {
    display: flex;
    align-items: flex-start;
    gap: 10px;
}

.rubis-img {
    max-width: 100px;
    height: auto;
}

.rubis-info {
    font-size: 9px;
    color: #222;
    line-height: 1.2;
    text-align: left;
}

.upper-box {
    border: 1.5px solid #888;
    height: 22px;
    width: 35%;
    border-radius: 4px;
    font-size: 8px;
    text-align: center;
    align-content: center;
    text-align:center;
}

.lower-box {
    border: 1.5px solid #888;
    height: 50px;
    width: 70%;
    border-radius: 4px;
    font-size: 8px;
    text-align:center;
}

.box-content {
    height: 100%;
    box-sizing: border-box;
}

.section-box {
    border: 1.5px solid #888;
    height: 32px;
    border-radius: 7px 7px 0px 0px;
    font-size: 9px;
    text-align: left;
    align-content: center;
    border-collapse: collapse !important;

}

.section-box-bottom {
    border-collapse: collapse !important;
    border: 1.5px solid #888;
    height: 32px;
    border-radius: 0px 0px 7px 7px;
    font-size: 9px;
    text-align: center;
    align-content: center;
}

.custom-table {
    border: 1.3px solid #9d8383;
    border-radius: 15px;
    margin: 20px auto;
    width: 96%;
    height: 330px;
    border-collapse: separate;
    overflow: hidden;
    position: relative;
    display: table;
}

.custom-table th,
.custom-table td {
    padding: 10px;
    text-align: left;
}

.custom-table th {
    border: none;
    color: black;
    font-size: 9px;
    border-bottom: 1px solid #9d8383;
    text-align: center;
    align-content: center;
    height: 26px;

}

.custom-table thead {
    border-bottom: 2px solid #9d8383;
}

.custom-table td {
    border: none;
}

.custom-table tbody {
    display: table-row-group;
    height: 100%; /* Ensure tbody takes available space */
}

.custom-table tfoot {
    font-size: 8px;
    display: table-footer-group;
    bottom: 0;
    left: 0;
    width: 100%;
}

.custom-table tfoot tr {
    height: auto;
    width: 100%;
}

.custom-table tfoot td {
    padding: 5px;
    box-sizing: border-box;
    vertical-align: top;
}

.custom-table-2 {
    border: 1.3px solid #9d8383;
    border-radius: 10px;
    margin: 20px auto;
    width: 96%;
    height: 40px;
    border-collapse: separate;
    overflow: hidden;
}

.custom-table-2 th {
    color: black;
    font-size: 9px;
    text-align: center;

}

body:last-child .print-format td img {
    width: 53% !important;
}

body:last-child .print-format td img.logo_qr {
    width: 40% !important;
}

.print-format td, .print-format th {
    padding: 0px !important;
}

@media print {
    .rubis-img {
        max-width: 100px !important;
        width: 53% !important;
        height: auto !important;
    }
    .print-format td img.rubis-img {
        width: 53% !important;
    }
   .print-format td img.logo_qr {
        width: 30% !important;
        height: auto !important;
    }
}
